<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';
import { confirmAction } from './confirmAction.js';

const props = defineProps({ materi: Object, studyGroups: { type: Array, default: () => [] }, filters: Object, selectedStudyGroup: Object });
const page = usePage();
const scope = computed(() => props.selectedStudyGroup?.uuid ? route('redesign.study-groups.guides', props.selectedStudyGroup.uuid) : route('redesign.materi'));
const items = computed(() => props.materi?.data || []);
const search = ref(props.filters?.search || '');
const view = computed(() => props.filters?.view || 'active');
const content = computed(() => props.filters?.content || '');
const currentTab = computed(() => view.value === 'trash' ? 'archive' : content.value === 'with' ? 'with' : content.value === 'without' ? 'without' : 'all');
const navigate = (overrides = {}) => router.get(scope.value, { search: search.value.trim() || undefined, view: view.value === 'trash' ? 'trash' : undefined, content: content.value || undefined, ...overrides }, { preserveState: true, preserveScroll: true, replace: true });
const setTab = tab => navigate(tab === 'archive' ? { view: 'trash', content: undefined } : { view: undefined, content: tab === 'all' ? undefined : tab });
const resetFilters = () => { search.value = ''; router.get(scope.value, {}, { preserveState: true, replace: true }); };
const archiveCandidate = ref(null);
const archive = () => router.delete(route('materi.destroy', archiveCandidate.value.uuid), { preserveScroll: true, onSuccess: () => { archiveCandidate.value = null; } });
const restore = item => router.patch(route('materi.restore', item.uuid), {}, { preserveScroll: true });
const hardDelete = async item => { if (await confirmAction(`Hapus permanen materi ${item.title}? Materi tidak dapat dipulihkan.`, 'Hapus permanen')) router.delete(route('materi.force-destroy', item.uuid), { preserveScroll: true }); };
const hasContent = item => Boolean(item.file_path || item.google_docs_embed_url || item.video_embed_url);
</script>

<template>
    <Head title="Perpustakaan materi" />
    <div class="library-app"><AdminSidebar /><main>
        <RedesignTopbar breadcrumb="Materi &amp; event" />
        <div class="content"><div class="heading"><div><Link v-if="selectedStudyGroup" :href="route('redesign.study-groups.show', selectedStudyGroup.uuid)" class="back">← {{ selectedStudyGroup.name }}</Link><h1>Perpustakaan materi</h1><p>Materi file, Google Docs, dan video untuk study group.</p></div><Link class="add" :href="selectedStudyGroup ? route('redesign.study-groups.guides.create', selectedStudyGroup.uuid) : route('redesign.materi.create')">+ Tambah materi</Link></div>
            <div class="tabs" role="group" aria-label="Kondisi materi"><button v-for="tab in [['all','Semua'],['with','Dengan konten'],['without','Tanpa konten'],['archive','Arsip']]" :key="tab[0]" type="button" :class="{ active: currentTab === tab[0] }" @click="setTab(tab[0])">{{ tab[1] }}</button></div>
            <form class="filters" @submit.prevent="navigate()"><input v-model="search" aria-label="Cari materi" placeholder="Cari judul, deskripsi, atau kelas..." /><button type="submit">Filter</button><button type="button" @click="resetFilters">Reset</button></form>
            <div v-if="!items.length" class="empty">{{ search ? 'Tidak ada materi yang cocok.' : 'Belum ada materi pada tampilan ini.' }}</div>
            <div v-else class="table-panel"><div class="table-wrap"><table><thead><tr><th scope="col">Judul materi</th><th scope="col">Kelas</th><th scope="col">Sumber</th><th scope="col">Kondisi</th><th scope="col">Aksi</th></tr></thead><tbody><tr v-for="item in items" :key="item.uuid"><td class="title-cell"><Link v-if="view !== 'trash'" :href="route('guides.user-preview', item.uuid)">{{ item.title }}</Link><strong v-else>{{ item.title }}</strong><small v-if="item.description">{{ item.description }}</small></td><td>{{ item.study_group?.name || 'Materi umum' }}</td><td>{{ item.google_docs_embed_url ? 'Google Docs' : item.video_embed_url ? 'Video' : item.file_path ? 'File' : 'Belum ada sumber' }}</td><td><span class="badge" :class="{ draft: !hasContent(item), archived: view === 'trash' }">{{ view === 'trash' ? 'Arsip' : hasContent(item) ? 'Dengan konten' : 'Tanpa konten' }}</span></td><td><div class="row-actions"><template v-if="view === 'trash'"><button type="button" @click="restore(item)">Pulihkan</button><button type="button" class="archive-action" @click="hardDelete(item)">Hapus permanen</button></template><template v-else><Link :href="route('guides.user-preview', item.uuid)">Detail</Link><Link :href="route('redesign.materi.edit', item.uuid)">Edit</Link><button type="button" class="archive-action" @click="archiveCandidate = item">Arsipkan</button></template></div></td></tr></tbody></table></div><div class="table-footer">Menampilkan {{ items.length }} dari {{ materi.total }} materi</div></div>
            <nav v-if="materi?.links?.length > 3" class="pagination" aria-label="Halaman materi"><Link v-for="(link, index) in materi.links" :key="index" :href="link.url || '#'" :class="{ active: link.active, disabled: !link.url }" :aria-disabled="!link.url" preserve-scroll v-html="link.label" /></nav>
        </div>
        <div v-if="archiveCandidate" class="overlay" @click.self="archiveCandidate = null"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="archive-title"><h2 id="archive-title">Arsipkan materi?</h2><p>{{ archiveCandidate.title }}</p><div class="dialog-actions"><button type="button" class="secondary" @click="archiveCandidate = null">Batal</button><button type="button" class="primary" @click="archive">Arsipkan</button></div></section></div>
    </main></div>
</template>

<style scoped>
